from pathlib import Path
import json,html,shutil
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'docs/manual/components'
OUT.mkdir(parents=True,exist_ok=True)
DATA=json.loads((OUT.parent/'data/components.json').read_text(encoding='utf8'))['components']
E=lambda s:html.escape(str(s))
css=(OUT.parent/'assets/component-base.css').read_text(encoding='utf8')
def port(p,side):
 return '<div class="port"><span class="letter">'+E(p['nickname'])+'</span><div><strong>'+E(p['name'])+'</strong><p>'+E(p['description'])+'</p><p class="small">'+E(p['type'])+' · '+('list of items' if p['access']=='list' else 'single item')+(' · optional' if side=='inputs' and p['optional'] else '')+('</p><p class="small">Default: '+E(', '.join(p['default'])) if p['default'] else '')+'</p></div></div>'
cards=[]
for c in DATA:
 cls=c['class']; incoming=[x for x in c['connections'] if x['target_guid']==c['guid']]; outgoing=[x for x in c['connections'] if x['source_guid']==c['guid']]
 wires=[]
 for x in incoming+outgoing:
  text=E(x['source_name']+' / '+x['source_port'])+' → '+E(x['target_name']+' / '+x['target_port'])
  if text not in wires:wires.append(text)
 examples=c['examples']; paths=[]
 for f in examples:
  source=ROOT/'tool/examples'/f.replace('.ghx','.gh')
  if not source.exists():source=ROOT/'teaching/roof_2d/output/case'/f.replace('.ghx','.gh')
  if source.exists():
   dest=OUT/'examples'/source.name;dest.parent.mkdir(exist_ok=True);shutil.copy2(source,dest);paths.append('<a href="examples/'+E(source.name)+'">'+E(source.stem.replace('_',' '))+'</a>')
 rows=''.join('<tr><td>'+E(side[:-1])+'</td><td>'+E(p['nickname']+' — '+p['name'])+'</td><td>'+E(p['type']+' / '+p['access'])+'</td><td>'+E(', '.join(p['default']) or ('Optional' if side=='inputs' and p['optional'] else 'No preset value'))+'</td></tr>' for side in ['inputs','outputs'] for p in c[side])
 cards.append('<article class="component-card" id="'+cls+'" data-dimension="'+c['dimension']+'" data-course="'+str(c['used_in_roof']).lower()+'"><section><p class="eyebrow">'+E(c['subcategory'])+' · '+E(c['dimension'])+(' · roof-rib course' if c['used_in_roof'] else '')+'</p><h1>'+E(c['name'])+'</h1><p class="intro">'+E(c['description'])+'</p><p class="location">Find it: '+E(c['category']+' → '+c['subcategory']+' → '+c['name'])+'</p><div class="anatomy"><div class="ports">'+''.join(port(p,'inputs') for p in c['inputs'])+'</div><figure class="component"><img loading="lazy" src="../assets/components/'+cls+'.png" alt="'+E(c['name'])+' with its actual input and output ports"><figcaption>Grasshopper capsule rendering using the installed component’s real layout. Neutral styling; not a live-session screenshot.</figcaption></figure><div class="ports out">'+''.join(port(p,'outputs') for p in c['outputs'])+'</div></div></section><section><p class="eyebrow">Connect it</p><h2>Verified wiring examples</h2>'+''.join('<div class="wire">'+w+'</div>' for w in wires)+'<p class="small">Connections extracted from the supplied Grasshopper definitions. These are wiring fragments: complete all remaining inputs before running.</p><p>'+ ' · '.join(paths)+'</p></section><section><p class="eyebrow">Try it</p><h2>Follow the data through this component.</h2><ol class="steps"><li><strong>Open a linked example.</strong><p>Find '+E(c['nickname'])+' and trace the wires entering the left-hand ports.</p></li><li><strong>Identify the data types.</strong><p>Match each connection to the port explanations above. Check whether it expects one item or a list.</p></li><li><strong>Inspect its outputs.</strong><p>Trace a right-hand wire to its destination. Read any Status or Info output in a Panel and inspect any available preview.</p></li><li><strong>Change one input at a time.</strong><p>Stop running jobs before editing. For solver controls, use a Button pulse for Run, Stop and Reset. Rerun dependent stages after changes.</p></li></ol><div class="check"><strong>Checkpoint</strong><p>Explain what this component receives, what it produces, and which downstream component uses the result. Check the exact port descriptions and defaults before choosing a value.</p></div></section><section><details><summary>Technical reference · exact types and defaults</summary><div class="table-wrap"><table><tr><th>Direction</th><th>Port</th><th>Type / access</th><th>Default</th></tr>'+rows+'</table></div></details></section></article>')
nav=''.join('<a href="#'+c['class']+'">'+E(c['nickname'])+'</a>' for c in DATA)
page='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TopOptLab — Complete Component Guide</title><style>'+css+'</style><link rel="stylesheet" href="../assets/port-layout.css"><main><header><span class="brand">TOP OPT LAB / COMPONENT GUIDE</span><span class="badge">33 COMPONENTS · 346 PORTS · ENGLISH</span></header><div class="hero"><h1>Understand every component.</h1><p class="intro">Recognise it. Connect it. Try it. A visual reference for the complete TopOptLab 0.4.0-dev component library.</p><p>Start with the 12 component types used in the roof-rib course, then explore the 3D and advanced workflows.</p></div><div class="filters"><input id="search" type="search" placeholder="Search components and ports" aria-label="Search components and ports"><select id="scope" aria-label="Filter components"><option value="all">All components</option><option value="course">Roof-rib course</option><option value="3D">3D and shared components</option><option value="2D">2D and shared components</option></select><span id="count" aria-live="polite">33 components</span></div><nav>'+nav+'</nav><section><h2>Before you begin</h2><p>Inputs enter on the left; outputs leave on the right. Drag between ports to create a wire. Hold Shift to add another source to an occupied input. A slider provides a number; a Toggle keeps a Boolean state; a Button provides a brief pulse.</p><p>Declare consistent geometry, force and material units. Density is a design variable, displacement is a physical response, and preview deformation scaling changes only the display. Compare independent load cases separately. A converged optimisation is not the same as a verified final shape.</p><p class="note">The plugin’s numerical stages are distinct: baseline FEM → optimisation → verification. 3D surface extraction and conforming final FEM introduce additional stages. Follow the matching example and inspect its reports.</p></section>'+''.join(cards)+'<footer>TopOptLab 0.4.0-dev · All 33 component types and 346 ports read from the installed GHA. English descriptions are the original plugin descriptions. Wiring verified against 21 supplied GHX definitions. Generated with the approved sample’s Grasshopper rendering method. This guide describes the software; structural qualification remains specific to the model and application.</footer></main><script>const cards=[...document.querySelectorAll(".component-card")];function filter(){let q=document.querySelector("#search").value.toLowerCase(),s=document.querySelector("#scope").value,n=0;cards.forEach(c=>{let ok=c.textContent.toLowerCase().includes(q)&&(s==="all"||s==="course"&&c.dataset.course==="true"||c.dataset.dimension.includes(s));c.hidden=!ok;if(ok)n++});document.querySelector("#count").textContent=n+" components"}document.querySelector("#search").addEventListener("input",filter);document.querySelector("#scope").addEventListener("change",filter);</script></html>'
(OUT/'index.html').write_text(page,encoding='utf8')
